def normalize_phone(s):
    if not isinstance(s, str):
        return None

    if any(not (c.isdigit() or c in " +-()") for c in s):
        return None

    s = s.replace(" ", "").replace("-", "").replace("(", "").replace(")", "")

    if s.startswith("+82"):
        s = "0" + s[3:]

    if len(s) != 11 or not s.startswith("010") or not s.isdigit():
        return None

    return f"{s[:3]}-{s[3:7]}-{s[7:]}"

