def format_krw(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")

    if n == 0:
        return "0원"

    sign = "-" if n < 0 else ""
    n = abs(n)

    eok, remainder = divmod(n, 100_000_000)
    man, won = divmod(remainder, 10_000)

    parts = []

    if eok:
        parts.append(f"{eok:,}억")
    if man:
        parts.append(f"{man:,}만")
    if won:
        parts.append(f"{won:,}")

    return sign + " ".join(parts) + "원"

