class Inventory:
    def __init__(self):
        self._stock = {}

    @staticmethod
    def _validate_name(name):
        if not isinstance(name, str) or not name:
            raise ValueError("name은 비어 있지 않은 문자열이어야 합니다.")

    @staticmethod
    def _validate_qty(qty):
        if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
            raise ValueError("qty는 양의 정수여야 합니다.")

    def add(self, name, qty):
        self._validate_name(name)
        self._validate_qty(qty)
        self._stock[name] = self._stock.get(name, 0) + qty

    def remove(self, name, qty):
        self._validate_name(name)
        self._validate_qty(qty)

        if name not in self._stock or self._stock[name] < qty:
            raise ValueError("품목이 없거나 재고가 부족합니다.")

        self._stock[name] -= qty

        if self._stock[name] == 0:
            del self._stock[name]

    def count(self, name):
        self._validate_name(name)
        return self._stock.get(name, 0)

    def low_stock(self, threshold):
        if isinstance(threshold, bool) or not isinstance(threshold, int):
            raise ValueError("threshold는 정수여야 합니다.")

        return sorted(
            name for name, qty in self._stock.items()
            if qty < threshold
        )

    def items(self):
        return self._stock.copy()

