        return []

    rows = []
    row = []
    field = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)

        else:
            if ch == '"':
                if not field:
                    in_quotes = True
                else:
                    field.append(ch)

            elif ch == ',':
                row.append(''.join(field))
                field = []

            elif ch == '\n':
                row.append(''.join(field))
                rows.append(row)
                row = []
                field = []

            elif ch == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    row.append(''.join(field))
                    rows.append(row)
                    row = []
                    field = []
                    i += 1
                else:
                    field.append(ch)

            else:
                field.append(ch)

        i += 1

    if in_quotes:
        raise ValueError("Unclosed quoted field")

    # 마지막 줄바꿈으로 인한 빈 행은 추가하지 않는다.
    if row or field or not text.endswith(('\n', '\r\n')):
        row.append(''.join(field))
        rows.append(row)

    return rows

