def evaluate(expr):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        if c.isspace():
            i += 1
        elif c.isdigit() or c == '.':
            start = i
            dots = 0

            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    dots += 1
                    if dots > 1:
                        raise ValueError("Invalid number")
                i += 1

            if expr[start:i] == '.':
                raise ValueError("Invalid number")

            tokens.append(float(expr[start:i]))
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError("Invalid character")

    pos = 0

    def parse_expression():
        nonlocal pos
        value = parse_term()

        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            value = value + right if op == '+' else value - right

        return value

    def parse_term():
        nonlocal pos
        value = parse_unary()

        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_unary()

            if op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right
            else:
                value *= right

        return value

    def parse_unary():
        nonlocal pos

        if pos < len(tokens) and tokens[pos] == '-':
            pos += 1
            return -parse_unary()

        if pos < len(tokens) and tokens[pos] == '+':
            pos += 1
            return parse_unary()

        return parse_primary()

    def parse_primary():
        nonlocal pos

        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[pos]

        if isinstance(token, float):
            pos += 1
            return token

        if token == '(':
            pos += 1
            value = parse_expression()

            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Unmatched parenthesis")

            pos += 1
            return value

        raise ValueError("Invalid syntax")

    if not tokens:
        raise ValueError("Empty expression")

    result = parse_expression()

    if pos != len(tokens):
        raise ValueError("Invalid syntax")

    return float(result)

